package ro.leo.visual;
import android.content.*;import org.json.*;import java.util.*;
/** Restorable destinations, never editor contents, credentials or phone numbers. */
final class WorkspaceSessions {
 static final Set<String> SAFE=new HashSet<String>(Arrays.asList("PhoneActivity","ContactsActivity","MessagesActivity","ClockActivity","MediaActivity","NowPlayingActivity","FilesActivity","CalendarActivity","RecorderActivity","NotesActivity","SettingsActivity","WeatherActivity","WebAppsActivity","GamesActivity"));
 static synchronized JSONArray read(Context c){try{return new JSONArray(c.getSharedPreferences("workspace",0).getString("screens","[]"));}catch(Exception e){return new JSONArray();}}
 static synchronized void record(Context c,String type,int selection){if(!SAFE.contains(type))return;try{JSONArray old=read(c),next=new JSONArray();next.put(new JSONObject().put("screen",type).put("selection",Math.max(0,Math.min(5000,selection))).put("time",System.currentTimeMillis()));for(int n=0;n<old.length()&&next.length()<12;n++)if(!type.equals(old.getJSONObject(n).optString("screen")))next.put(old.getJSONObject(n));c.getSharedPreferences("workspace",0).edit().putString("screens",next.toString()).apply();}catch(Exception ignored){}}
 static synchronized void recordWeb(Context c,String id){if(!WebAppPackages.validId(id))return;try{JSONArray old=read(c),next=new JSONArray();next.put(new JSONObject().put("screen","WebRuntimeActivity").put("web_app",id).put("selection",0).put("time",System.currentTimeMillis()));for(int n=0;n<old.length()&&next.length()<12;n++){JSONObject row=old.getJSONObject(n);if(!id.equals(row.optString("web_app")))next.put(row);}c.getSharedPreferences("workspace",0).edit().putString("screens",next.toString()).apply();}catch(Exception ignored){}}
 static Intent destination(Context c,JSONObject row){String screen=row.optString("screen");if(screen.equals("WebRuntimeActivity")){String id=row.optString("web_app");if(!WebAppPackages.validId(id))throw new SecurityException();return new Intent(c,WebRuntimeActivity.class).putExtra("web_app",id).addFlags(Intent.FLAG_ACTIVITY_NEW_DOCUMENT);}return destination(c,screen);}
 static String label(JSONObject row){String screen=row.optString("screen");if(screen.equals("WebRuntimeActivity"))return row.optString("web_app")+" · Web";String[] types={"PhoneActivity","ContactsActivity","MessagesActivity","ClockActivity","MediaActivity","FilesActivity","CalendarActivity","RecorderActivity","NotesActivity","SettingsActivity","WeatherActivity","WebAppsActivity","GamesActivity"};int[] ids={0,1,2,3,6,7,11,13,10,8,26,37,31};for(int n=0;n<types.length;n++)if(types[n].equals(screen))return AppCatalog.NAMES[ids[n]];return screen.replace("Activity","");}
 static int selection(Context c,String type){JSONArray rows=read(c);for(int n=0;n<rows.length();n++){JSONObject row=rows.optJSONObject(n);if(row!=null&&type.equals(row.optString("screen")))return Math.max(0,Math.min(5000,row.optInt("selection")));}return 0;}
 static Intent destination(Context c,String type){if(!SAFE.contains(type))throw new SecurityException();return new Intent().setClassName(c,"ro.leo.visual."+type).putExtra("workspace_resume",true);}
}
